enum OrderStatus {
  Pending = 0,
  Shipped = 1,
  Delivered = 2,
}

const VALID = new Set<number>([
  OrderStatus.Pending,
  OrderStatus.Shipped,
  OrderStatus.Delivered,
]);

function parseStatus(raw: number): OrderStatus {
  if (!VALID.has(raw)) throw new Error(`Invalid status: ${raw}`);
  return raw as OrderStatus;
}
